function shuffle(n, seed){ const a=[...Array(n).keys()]; let s=seed>>>0||1; const rnd=()=>(s=(s*1664525+1013904223)>>>0)/4294967296; for(let i=n-1;i>0;i--){const j=Math.floor(rnd()*(i+1));[a[i],a[j]]=[a[j],a[i]];} return a; }
